  OR r->'notifications' IS DISTINCT FROM '[]'::jsonb
  OR (SELECT coalesce(gigs_completed,0) FROM public."User" WHERE id=worker)<>1
  OR (SELECT count(*) FROM public."Notification" WHERE metadata->>'gig_id'=g::text)<>note_count+1
