 r:=public.confirm_gig_completion(g,u,expected,NULL,NULL);
 IF r->'gig'->>'owner_confirmed_at' IS NULL OR (SELECT coalesce(gigs_completed,0) FROM public."User" WHERE id=worker)<>2 THEN
